const el = document.getElementById('container');
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = el.offsetWidth || 400; canvas.height = el.offsetHeight || 500;
el.appendChild(canvas);

let particles = [];
const mouse = { x: -1000, y: -1000, radius: 80 };

function initText() {
  ctx.fillStyle = 'white';
  ctx.font = '900 60px sans-serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('SHATTER', canvas.width/2, canvas.height/2);

  const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  for(let y=0; y<canvas.height; y+=4){
    for(let x=0; x<canvas.width; x+=4){
      if(data[(y * canvas.width + x) * 4 + 3] > 128) {
        particles.push({
          x: x, y: y, baseX: x, baseY: y,
          color: `hsl(${Math.random()*60 + 280}, 100%, 60%)` // ગુલાબી-જાંબલી શેડ્સ
        });
      }
    }
  }
}
initText();

el.addEventListener('pointermove', (e) => {
  const rect = el.getBoundingClientRect();
  mouse.x = e.clientX - rect.left; mouse.y = e.clientY - rect.top;
});
el.addEventListener('pointerleave', () => { mouse.x = -1000; mouse.y = -1000; });

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  particles.forEach(p => {
    let dx = mouse.x - p.x; let dy = mouse.y - p.y;
    let dist = Math.sqrt(dx*dx + dy*dy);
    let forceDirectionX = dx / dist; let forceDirectionY = dy / dist;

    // જો કર્સર નજીક આવે તો પાર્ટીકલ્સ વિખેરાઈ જશે
    if(dist < mouse.radius) {
      let force = (mouse.radius - dist) / mouse.radius;
      p.x -= forceDirectionX * force * 10; p.y -= forceDirectionY * force * 10;
    } else {
      // કર્સર દૂર જાય એટલે પાછા પોતાની જગ્યાએ ગોઠવાઈ જશે
      if(p.x !== p.baseX) p.x -= (p.x - p.baseX) * 0.1;
      if(p.y !== p.baseY) p.y -= (p.y - p.baseY) * 0.1;
    }
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x, p.y, 3, 3);
  });
  requestAnimationFrame(draw);
}
draw();
